-- schemas/schema.sql
--
-- Reference dump of `loom.*` and `loom_telemetry.*`: what replaying schemas/migrations/*.sql
-- produces, auto-generated by scripts/ops/dump_schema.py from a live
-- ClickHouse that has every migration applied. Read it to see the current
-- shape of a table or view.
--
-- This is NOT an install path. Applying it directly skips the migration
-- ledger and the rewrites the runner makes at apply time (session settings,
-- server-specific clauses). Install or upgrade with:
--     loom migrate
--
-- This file is regenerated whenever migrations change:
--     make schema-dump
--
-- Do NOT hand-edit. Edit schemas/migrations/*.sql and re-dump.
-- CI verifies this file matches what migrations would produce.
--
-- Counts: 177 tables + 19 materialized views.

CREATE DATABASE IF NOT EXISTS `loom`;
CREATE DATABASE IF NOT EXISTS `loom_telemetry`;

-- ======================================================================
-- Tables (177)
-- ======================================================================

-- loom.acl_versions
CREATE TABLE IF NOT EXISTS loom.acl_versions
(
    `org` LowCardinality(String),
    `kind` LowCardinality(String),
    `changes` UInt64 DEFAULT 1,
    `updated_at` DateTime64(3) DEFAULT now64(3)
)
ENGINE = SummingMergeTree(changes)
ORDER BY (org, kind)
SETTINGS allow_dimensions_outside_sorting_key = 1, non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.agent_cost_rollup_daily
CREATE TABLE IF NOT EXISTS loom.agent_cost_rollup_daily
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `day` Date,
    `operation` LowCardinality(String),
    `cost_usd_state` AggregateFunction(sum, Decimal(18, 6)),
    `tokens_state` AggregateFunction(sum, UInt64),
    `embed_tokens_state` AggregateFunction(sum, UInt64),
    `ops_state` AggregateFunction(count),
    `errors_state` AggregateFunction(sum, UInt64),
    `latency_sum_state` AggregateFunction(sum, UInt64),
    `latency_quantile_state` AggregateFunction(quantiles(0.5, 0.95, 0.99), UInt32),
    `ts_hwm` SimpleAggregateFunction(max, DateTime64(3)) DEFAULT toDateTime64(0, 3)
)
ENGINE = AggregatingMergeTree
PARTITION BY toYYYYMM(day)
ORDER BY (org, namespace, agent, day, operation)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.agent_events
CREATE TABLE IF NOT EXISTS loom.agent_events
(
    `ts` DateTime64(3) DEFAULT now64(),
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String,
    `session_id` String,
    `run_id` String DEFAULT '',
    `operation` LowCardinality(String),
    `request_id` String,
    `trace_id` String DEFAULT '',
    `latency_ms` UInt32,
    `input_tokens` UInt32 DEFAULT 0,
    `output_tokens` UInt32 DEFAULT 0,
    `embedding_tokens` UInt32 DEFAULT 0,
    `upstream_cost_usd` Decimal(18, 6) DEFAULT 0,
    `bytes_written` UInt64 DEFAULT 0,
    `success` Bool,
    `error_code` LowCardinality(String) DEFAULT '',
    `memory_key` String DEFAULT '',
    `impersonated_by` String DEFAULT '',
    `kind` LowCardinality(String) DEFAULT '',
    `args` Map(LowCardinality(String), String) DEFAULT map(),
    `model` LowCardinality(String) DEFAULT '',
    `llm_calls` UInt16 DEFAULT 0,
    `build_commit` LowCardinality(String) DEFAULT '',
    `instance` LowCardinality(String) DEFAULT '',
    `instance_label` LowCardinality(String) DEFAULT '',
    `consumer` LowCardinality(String) DEFAULT '',
    `response_tokens` UInt32 DEFAULT 0,
    `traffic_class` LowCardinality(String) DEFAULT '',
    `subject` LowCardinality(String) DEFAULT '',
    `transport` LowCardinality(String) DEFAULT '',
    `slo_class` LowCardinality(String) DEFAULT '',
    `status_class` LowCardinality(String) DEFAULT '',
    `budget_ms` UInt32 DEFAULT 0,
    `ingested_at` DateTime64(3) DEFAULT now64(3),
    INDEX run_id_bloom_idx run_id TYPE bloom_filter(0.01) GRANULARITY 1,
    INDEX ingested_at_idx ingested_at TYPE minmax GRANULARITY 1
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, agent, ts)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

