-- loom.chunks
CREATE TABLE IF NOT EXISTS loom.chunks
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `source_uri` String,
    `chunk_idx` UInt32,
    `content` String,
    `context` String DEFAULT '',
    `context_lc` String MATERIALIZED lowerUTF8(context),
    `content_lc` String MATERIALIZED lowerUTF8(content),
    `tags` Array(LowCardinality(String)),
    `doc_metadata` String DEFAULT '{}',
    `chunk_metadata` String DEFAULT '{}',
    `ingested_at` DateTime DEFAULT now(),
    `doc_superseded_at` Nullable(DateTime),
    `embedding_model` LowCardinality(String),
    `embedding_dim` UInt16 DEFAULT 0,
    `embedding` Array(BFloat16) CODEC(Quantized('rabitq', 3072, 0)),
    `created_at` DateTime DEFAULT now(),
    `embed_attempts` UInt16 DEFAULT 0,
    `embed_last_error` String DEFAULT '',
    `embed_failed_at` Nullable(DateTime),
    `content_sha256` String DEFAULT '',
    `doc_version` UInt64 DEFAULT 0,
    `agent` LowCardinality(String) DEFAULT '-',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `source_class` LowCardinality(String) DEFAULT '',
    `keys` Array(String) DEFAULT [],
    `embed_input_sha256` String DEFAULT '',
    INDEX tags_bloom tags TYPE bloom_filter() GRANULARITY 1,
    INDEX content_text content_lc TYPE text(tokenizer = 'splitByNonAlpha') GRANULARITY 100000000,
    INDEX context_text context_lc TYPE text(tokenizer = 'splitByNonAlpha') GRANULARITY 100000000,
    INDEX keys_bloom keys TYPE bloom_filter() GRANULARITY 1,
    INDEX embed_input_bloom embed_input_sha256 TYPE bloom_filter() GRANULARITY 1
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, embedding_model, source_uri, chunk_idx)
SETTINGS index_granularity = 8192, exclude_materialize_skip_indexes_on_merge = 'content_text,context_text', non_replicated_deduplication_window = 1000;

