-- loom.code_call_sites_unresolved
CREATE TABLE IF NOT EXISTS loom.code_call_sites_unresolved
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `callee_name` String CODEC(ZSTD(3)),
    `path` String CODEC(ZSTD(3)),
    `line` UInt32 DEFAULT 0,
    `from_symbol_id` String CODEC(ZSTD(3)),
    `from_qualified_name` String DEFAULT '' CODEC(ZSTD(3)),
    `call_text` String DEFAULT '' CODEC(ZSTD(3)),
    `disposition` Enum8('unresolved' = 1, 'ambiguous' = 2),
    `candidates` UInt16 DEFAULT 0,
    `indexed_commit` FixedString(40) DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `created_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    INDEX idx_code_call_miss_path path TYPE bloom_filter(0.01) GRANULARITY 4,
    PROJECTION by_path
    (
        SELECT *
        ORDER BY
            org,
            namespace,
            path,
            line,
            callee_name,
            from_symbol_id
    )
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, callee_name, path, line, from_symbol_id)
SETTINGS index_granularity = 8192, deduplicate_merge_projection_mode = 'rebuild', lightweight_mutation_projection_mode = 'rebuild', non_replicated_deduplication_window = 1000;

