    `site_callees` Array(UInt32) DEFAULT [] CODEC(ZSTD(3)),
    `site_guards` Array(Array(UInt8)) DEFAULT [] CODEC(ZSTD(3)),
    `indexed_commit` FixedString(40) DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `created_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))) CODEC(T64, ZSTD(3)),
    INDEX idx_code_caller_guards_path path TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, from_symbol_id, path)
SETTINGS index_granularity = 1024, non_replicated_deduplication_window = 1000;

-- loom.code_chunks
CREATE TABLE IF NOT EXISTS loom.code_chunks
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `embedding_model` LowCardinality(String),
    `path` String,
    `chunk_id` UUID,
    `scope` String DEFAULT '',
    `kind` Enum8('function' = 1, 'class_skeleton' = 2, 'comment_block' = 3, 'file_header' = 4, 'other' = 5) DEFAULT 'other',
    `start_line` UInt32 DEFAULT 0,
    `end_line` UInt32 DEFAULT 0,
    `content` String CODEC(ZSTD(1)),
    `content_hash` FixedString(64) DEFAULT '',
    `context_text` String DEFAULT '',
    `context_description` String DEFAULT '',
    `context_source` Enum8('structural' = 1, 'llm' = 2) DEFAULT 'structural',
    `lexemes` String DEFAULT '',
    `symbol_ids` Array(String) DEFAULT [],
    `embedding` Array(BFloat16) DEFAULT [] CODEC(Quantized('rabitq', 3072, 0)),
    `embedding_dim` UInt16 DEFAULT 0,
    `embed_attempts` UInt16 DEFAULT 0,
    `embed_last_error` String DEFAULT '',
    `embed_failed_at` Nullable(DateTime) DEFAULT NULL,
    `indexed_commit` FixedString(40) DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `created_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    INDEX idx_code_chunks_hash content_hash TYPE bloom_filter GRANULARITY 4,
    INDEX idx_code_chunks_symbols symbol_ids TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX idx_code_chunks_content_ng lower(content) TYPE text(tokenizer = ngrams(3)) GRANULARITY 100000000,
    INDEX idx_code_chunks_lexemes lexemes TYPE text(tokenizer = splitByNonAlpha) GRANULARITY 100000000
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY (org, namespace)
ORDER BY (org, namespace, embedding_model, path, chunk_id)
SETTINGS index_granularity = 256, min_bytes_for_wide_part = 134217728, non_replicated_deduplication_window = 1000;

