-- loom.code_edges
CREATE TABLE IF NOT EXISTS loom.code_edges
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `tier` Enum8('treesitter' = 1, 'scip' = 2),
    `edge_kind` Enum8('calls' = 1, 'includes' = 2, 'inherits' = 3, 'overrides' = 4, 'uses_type' = 5, 'fixture_use' = 6, 'reads' = 7, 'writes' = 8),
    `to_symbol_id` String,
    `from_symbol_id` String CODEC(ZSTD(3)),
    `path` String CODEC(ZSTD(3)),
    `line` UInt32 DEFAULT 0,
    `from_qualified_name` String DEFAULT '' CODEC(ZSTD(3)),
    `to_qualified_name` String DEFAULT '' CODEC(ZSTD(3)),
    `confidence` Float32 DEFAULT 1,
    `indexed_commit` FixedString(40) DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `created_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    INDEX idx_code_edges_from from_symbol_id TYPE bloom_filter GRANULARITY 4,
    INDEX idx_code_edges_path path TYPE bloom_filter(0.01) GRANULARITY 4,
    PROJECTION by_path
    (
        SELECT *
        ORDER BY
            org,
            namespace,
            tier,
            path,
            line
    ),
    PROJECTION by_from
    (
        SELECT *
        ORDER BY
            org,
            namespace,
            tier,
            from_symbol_id,
            edge_kind,
            to_symbol_id,
            path,
            line
    )
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, tier, to_symbol_id, edge_kind, from_symbol_id, path, line)
SETTINGS index_granularity = 1024, deduplicate_merge_projection_mode = 'rebuild', lightweight_mutation_projection_mode = 'rebuild', non_replicated_deduplication_window = 1000;

