CREATE TABLE IF NOT EXISTS loom.consolidation_runs
(
    `run_id` UUID DEFAULT generateUUIDv4(),
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String,
    `source_memory_ids` Array(UUID),
    `source_memory_keys` Array(String),
    `cluster_size` UInt32,
    `cluster_cohesion` Float32,
    `output_memory_id` Nullable(UUID),
    `output_memory_key` String,
    `memory_type` LowCardinality(String),
    `llm_provider` LowCardinality(String) DEFAULT '',
    `llm_model` LowCardinality(String) DEFAULT '',
    `tokens_in` UInt32 DEFAULT 0,
    `tokens_out` UInt32 DEFAULT 0,
    `duration_ms` UInt32 DEFAULT 0,
    `status` Enum8('written' = 1, 'skipped' = 2, 'failed' = 3) DEFAULT 'written',
    `failure_reason` String DEFAULT '',
    `ran_at` DateTime DEFAULT now()
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ran_at)
ORDER BY (org, namespace, ran_at, run_id)
TTL ran_at + toIntervalDay(180)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.context_blobs
CREATE TABLE IF NOT EXISTS loom.context_blobs
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `run_id` String DEFAULT '-',
    `blob_key` String,
    `content` String CODEC(ZSTD(3)),
    `content_bytes` UInt32 DEFAULT 0,
    `content_type` LowCardinality(String) DEFAULT 'text/plain',
    `summary` String DEFAULT '',
    `sha256` String DEFAULT '',
    `created_at` DateTime DEFAULT now(),
    `expires_at` DateTime,
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY toYYYYMM(expires_at)
ORDER BY (org, namespace, blob_key)
TTL expires_at + toIntervalDay(1)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.conversation_embeddings
CREATE TABLE IF NOT EXISTS loom.conversation_embeddings
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `thread_id` String,
    `msg_id` String,
    `role` LowCardinality(String),
    `content_excerpt` String,
    `embedding_model` LowCardinality(String),
    `embedding_dim` UInt16 DEFAULT 0,
    `embedding` Array(BFloat16) CODEC(Quantized('rabitq', 3072, 0)),
    `user_id` String DEFAULT '-',
    `embed_attempts` UInt16 DEFAULT 0,
    `embed_last_error` String DEFAULT '',
    `embed_failed_at` Nullable(DateTime),
    `ts` DateTime64(3, 'UTC') DEFAULT now64(3),
    `run_id` String DEFAULT '-',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `is_saved` Bool DEFAULT false,
    `saved_at` Nullable(DateTime64(3, 'UTC')) DEFAULT if(is_saved, ts, NULL)
)
ENGINE = ReplacingMergeTree(ts)
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, embedding_model, thread_id, msg_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.conversation_threads
CREATE TABLE IF NOT EXISTS loom.conversation_threads
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `thread_id` String,
    `title` String DEFAULT '',
    `metadata` String DEFAULT '{}',
    `run_id` String DEFAULT '-',
    `user_id` String DEFAULT '-',
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = ReplacingMergeTree(updated_at)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, thread_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.conversations
CREATE TABLE IF NOT EXISTS loom.conversations
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `thread_id` String,
    `msg_id` String,
    `role` Enum8('user' = 1, 'assistant' = 2, 'system' = 3, 'tool' = 4),
    `content` String,
    `user_id` String DEFAULT '-',
    `metadata` String DEFAULT '{}',
    `tokens` UInt32 DEFAULT 0,
    `ts` DateTime64(3, 'UTC') DEFAULT now64(3),
    `run_id` String DEFAULT '-',
    `reasoning` String DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `is_saved` Bool DEFAULT false,
    `saved_at` Nullable(DateTime64(3, 'UTC')) DEFAULT if(is_saved, ts, NULL)
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, thread_id, ts, msg_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.delete_version_checks
CREATE TABLE IF NOT EXISTS loom.delete_version_checks
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` String,
    `user_id` String,
    `session_id` String,
    `memory_key` String,
    `checked` UInt64,
    `tombstone` UInt64,
    `done` UInt8 DEFAULT 0,
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime64(3) DEFAULT now64(3)
)
ENGINE = ReplacingMergeTree(updated_at)
ORDER BY (org, namespace, agent, user_id, session_id, memory_key, tombstone)
TTL created_at + toIntervalDay(30)
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.deployment_config
CREATE TABLE IF NOT EXISTS loom.deployment_config
(
    `name` LowCardinality(String),
    `value` String CODEC(ZSTD(3)),
    `published_by` String DEFAULT '',
    `build_commit` String DEFAULT '',
    `published_at` DateTime64(3) DEFAULT now64(3),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
ORDER BY name
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.derived_facts
CREATE TABLE IF NOT EXISTS loom.derived_facts
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String) DEFAULT '',
    `user_id` String DEFAULT '',
    `memory_key` String,
    `subject` LowCardinality(String),
    `predicate` LowCardinality(String),
    `object` String,
    `category` LowCardinality(String) DEFAULT '',
    `numeric_value` Nullable(Float64) DEFAULT NULL,
    `unit` LowCardinality(String) DEFAULT '',
    `occurred_at` Nullable(DateTime) DEFAULT NULL,
    `session_id` String DEFAULT '',
    `confidence` Float32 DEFAULT 1.,
    `created_at` DateTime DEFAULT now()
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, subject, predicate, category)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.document_blobs
CREATE TABLE IF NOT EXISTS loom.document_blobs
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `sha256` FixedString(64),
    `data` String CODEC(ZSTD(3)),
    `size` UInt64,
    `created_at` DateTime64(3) DEFAULT now64(3),
    `location` String DEFAULT ''
)
ENGINE = ReplacingMergeTree(created_at)
ORDER BY (org, namespace, sha256)
SETTINGS index_granularity = 128, non_replicated_deduplication_window = 1000;

-- loom.documents
CREATE TABLE IF NOT EXISTS loom.documents
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `source_uri` String,
    `doc_id` UUID DEFAULT generateUUIDv4(),
    `title` String DEFAULT '',
    `content` String,
    `tags` Array(LowCardinality(String)),
    `metadata` String DEFAULT '{}',
    `version` UInt64,
    `superseded_at` Nullable(DateTime),
    `ingested_at` DateTime DEFAULT now(),
    `content_sha256` String DEFAULT '',
    `blob_path` String DEFAULT '',
    `blob_size` UInt64 DEFAULT 0,
    `blob_content_type` LowCardinality(String) DEFAULT '',
    `original_filename` String DEFAULT '',
    `description` String DEFAULT '',
    `blob_erased_at` Nullable(DateTime) DEFAULT NULL,
    `content_preview` String MATERIALIZED substring(content, 1, 220),
    `agent` LowCardinality(String) DEFAULT '-',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `actor` String DEFAULT '',
    `source_class` LowCardinality(String) DEFAULT '',
    `revision` UInt64 DEFAULT 0,
    `format` LowCardinality(String) DEFAULT '',
    `artifact_sha256` String DEFAULT '',
    `parser` String DEFAULT '',
    `coverage` String DEFAULT '',
    `ingestion_id` String DEFAULT '',
    INDEX tags_bloom tags TYPE bloom_filter() GRANULARITY 1
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY toYYYYMM(ingested_at)
ORDER BY (org, namespace, source_uri)
SETTINGS index_granularity = 64, non_replicated_deduplication_window = 1000;

-- loom.embedder_calibration
CREATE TABLE IF NOT EXISTS loom.embedder_calibration
(
    `embedder_model` LowCardinality(String),
    `thresholds_json` String,
    `calibration_hash` String,
    `calibrated_by` String,
    `calibrated_at` DateTime DEFAULT now(),
    `version` UInt64
)
ENGINE = ReplacingMergeTree(version)
ORDER BY embedder_model
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.embedding_cache
CREATE TABLE IF NOT EXISTS loom.embedding_cache
(
    `model` LowCardinality(String),
    `key` String,
    `dim` UInt16,
    `embedding` Array(Float32),
    `created_at` DateTime DEFAULT now(),
    `org` LowCardinality(String) DEFAULT ''
)
ENGINE = ReplacingMergeTree(created_at)
ORDER BY (model, key)
TTL created_at + toIntervalDay(30)
SETTINGS index_granularity = 32, non_replicated_deduplication_window = 1000;

-- loom.entity_canonical_map
CREATE TABLE IF NOT EXISTS loom.entity_canonical_map
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `mention_text` String,
    `canonical_text` String,
    `confidence` Float32 DEFAULT 1.,
    `strategy` LowCardinality(String) DEFAULT 'self',
    `evidence_count` UInt32 DEFAULT 1,
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    INDEX idx_canonical_text canonical_text TYPE bloom_filter GRANULARITY 4
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY org
ORDER BY (org, namespace, mention_text)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_communities
CREATE TABLE IF NOT EXISTS loom.entity_communities
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `level` UInt8 DEFAULT 0,
    `entity` LowCardinality(String),
    `community_id` UInt32,
    `label` String DEFAULT '',
    `size` UInt32 DEFAULT 0,
    `degree` UInt32 DEFAULT 0,
    `computed_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, level, entity)
SETTINGS index_granularity = 256, non_replicated_deduplication_window = 1000;

-- loom.entity_degree
CREATE TABLE IF NOT EXISTS loom.entity_degree
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `entity` LowCardinality(String),
    `degree` UInt32
)
ENGINE = SummingMergeTree
ORDER BY (org, namespace, entity)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_edge_memories
CREATE TABLE IF NOT EXISTS loom.entity_edge_memories
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `entity_a` LowCardinality(String),
    `entity_b` LowCardinality(String),
    `memory_key` String,
    `seen_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(seen_at)
PARTITION BY toYYYYMM(seen_at)
ORDER BY (org, namespace, entity_a, entity_b, memory_key)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_edge_rows
CREATE TABLE IF NOT EXISTS loom.entity_edge_rows
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `memory_id` UUID,
    `user_id` String,
    `content_sha256` FixedString(64),
    `entity_a` LowCardinality(String),
    `entity_b` LowCardinality(String),
    INDEX pair_skip (entity_a, entity_b) TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree
ORDER BY (org, namespace, memory_id, user_id, content_sha256, entity_a, entity_b)
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.entity_edges
CREATE TABLE IF NOT EXISTS loom.entity_edges
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `entity_a` LowCardinality(String),
    `entity_b` LowCardinality(String),
    `co_occur` UInt32 DEFAULT 1,
    `last_seen` SimpleAggregateFunction(max, DateTime) DEFAULT now(),
    `valid_from` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `invalid_at` Nullable(DateTime) DEFAULT NULL,
    `restore_id` String DEFAULT '',
    `closed_by` String DEFAULT '',
    INDEX idx_valid_from_minmax valid_from TYPE minmax GRANULARITY 8,
    INDEX idx_valid_to_minmax valid_to TYPE minmax GRANULARITY 8,
    INDEX idx_invalid_at_minmax invalid_at TYPE minmax GRANULARITY 8
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(last_seen)
ORDER BY (org, namespace, entity_a, entity_b)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_summaries
CREATE TABLE IF NOT EXISTS loom.entity_summaries
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String) DEFAULT '-',
    `user_id` String DEFAULT '-',
    `entity` String,
    `summary_text` String,
    `summary_embedding` Array(BFloat16) CODEC(Quantized('rabitq', 3072, 0)),
    `embedding_model` LowCardinality(String),
    `embedding_dim` UInt16 DEFAULT 0,
    `key_facts` Array(String) DEFAULT [],
    `fact_count` UInt32 DEFAULT 0,
    `valid_from` Nullable(DateTime) DEFAULT NULL,
    `updated_at` DateTime DEFAULT now(),
    `created_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, agent, user_id, entity, embedding_model)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_triple_memories
CREATE TABLE IF NOT EXISTS loom.entity_triple_memories
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `subject` LowCardinality(String),
    `relation` LowCardinality(String),
    `object` LowCardinality(String),
    `memory_key` String,
    `seen_at` DateTime DEFAULT now(),
    `confidence` Float32 DEFAULT 1.,
    `adapter_name` LowCardinality(String) DEFAULT ''
)
ENGINE = ReplacingMergeTree(seen_at)
PARTITION BY toYYYYMM(seen_at)
ORDER BY (org, namespace, subject, relation, object, memory_key)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_triple_rows
CREATE TABLE IF NOT EXISTS loom.entity_triple_rows
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `memory_id` UUID,
    `user_id` String,
    `content_sha256` FixedString(64),
    `subject` LowCardinality(String),
    `relation` LowCardinality(String),
    `object` LowCardinality(String),
    `inferred` Bool,
    INDEX triple_skip (subject, relation, object) TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree
ORDER BY (org, namespace, memory_id, user_id, content_sha256, subject, relation, object, inferred)
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.entity_triples
CREATE TABLE IF NOT EXISTS loom.entity_triples
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `subject` LowCardinality(String),
    `relation` LowCardinality(String),
    `object` LowCardinality(String),
    `co_occur` UInt32 DEFAULT 1,
    `last_seen` SimpleAggregateFunction(max, DateTime) DEFAULT now(),
    `confidence` Float32 DEFAULT 1.,
    `provenance` LowCardinality(String) DEFAULT '',
    `adapter_name` LowCardinality(String) DEFAULT '',
    `valid_from` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `invalid_at` Nullable(DateTime) DEFAULT NULL,
    `seen_at` DateTime64(6) DEFAULT toDateTime64(last_seen, 6),
    `restore_id` String DEFAULT '',
    INDEX idx_valid_from_minmax valid_from TYPE minmax GRANULARITY 8,
    INDEX idx_valid_to_minmax valid_to TYPE minmax GRANULARITY 8,
    INDEX idx_invalid_at_minmax invalid_at TYPE minmax GRANULARITY 8
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(last_seen)
ORDER BY (org, namespace, subject, relation, object)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.entity_vectors
CREATE TABLE IF NOT EXISTS loom.entity_vectors
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String,
    `entity_text` LowCardinality(String),
    `entity_embedding` Array(BFloat16) CODEC(Quantized('rabitq', 3072, 0), LZ4),
    `embedding_model` LowCardinality(String),
    `embedding_dim` UInt16 DEFAULT 0,
    `memory_key` String,
    `created_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime)
)
ENGINE = ReplacingMergeTree(created_at)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, agent, user_id, entity_text, memory_key)
SETTINGS index_granularity = 256, min_bytes_for_wide_part = 134217728, non_replicated_deduplication_window = 1000;

-- loom.erasure_requests
CREATE TABLE IF NOT EXISTS loom.erasure_requests
(
    `id` UUID,
    `org` LowCardinality(String),
    `scope_type` LowCardinality(String),
    `scope_value` String,
    `requester` String,
    `urgency` LowCardinality(String) DEFAULT 'normal',
    `status` Enum8('queued' = 1, 'in_progress' = 2, 'completed' = 3, 'failed' = 4),
    `current_step` UInt8 DEFAULT 0,
    `failure_reason` String DEFAULT '',
    `requested_at` DateTime DEFAULT now(),
    `completed_at` Nullable(DateTime),
    `version` UInt64,
    `steps_completed` Array(LowCardinality(String)) DEFAULT [],
    `attempts` UInt16 DEFAULT 1,
    `last_checkpoint_at` DateTime DEFAULT now(),
    `residue_count` UInt32 DEFAULT 0,
    `residue` String DEFAULT '',
    `verified_at` Nullable(DateTime) DEFAULT NULL,
    `purge` Bool DEFAULT false,
    `actor` String DEFAULT ''
)
ENGINE = ReplacingMergeTree(version)
ORDER BY id
TTL requested_at + toIntervalDay(90)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.erasure_reversals
CREATE TABLE IF NOT EXISTS loom.erasure_reversals
(
    `erasure_id` UUID,
    `org` LowCardinality(String),
    `scope_type` LowCardinality(String),
    `scope_value` String,
    `memory_id` String,
    `memory_key` String,
    `restored_at` DateTime DEFAULT now(),
    `restored_by` String DEFAULT '',
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, erasure_id, memory_id)
TTL restored_at + toIntervalYear(5)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.events
CREATE TABLE IF NOT EXISTS loom.events
(
    `ts` DateTime64(3) DEFAULT now64(3),
    `kind` LowCardinality(String),
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String) DEFAULT '',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `run_id` String DEFAULT '-',
    `request_id` String DEFAULT '',
    `actor` String DEFAULT '',
    `token_id` String DEFAULT '',
    `build_commit` LowCardinality(String) DEFAULT '',
    `instance` LowCardinality(String) DEFAULT '',
    `instance_label` LowCardinality(String) DEFAULT '',
    `keys` Array(String) DEFAULT [],
    `scores` Array(Float32) DEFAULT [],
    `embedding` Array(BFloat16) DEFAULT [],
    `payload` String DEFAULT '{}'
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, kind, ts)
TTL toDateTime(ts) + toIntervalDay(30)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.extraction_policies
CREATE TABLE IF NOT EXISTS loom.extraction_policies
(
    `org` String,
    `namespace` String,
    `policy` String,
    `updated_by` String,
    `updated_at` DateTime64(3, 'UTC'),
    `deleted` UInt8,
    `version` UInt64
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace)
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.frontend_assets
CREATE TABLE IF NOT EXISTS loom.frontend_assets
(
    `path` String,
    `sha256` String,
    `body` String CODEC(ZSTD(3)),
    `size` UInt32,
    `published_by` String,
    `published_at` DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(published_at)
ORDER BY path
TTL published_at + toIntervalDay(30)
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.grant_claims
CREATE TABLE IF NOT EXISTS loom.grant_claims
(
    `claim_key` String,
    `holder` String,
    `claimed_at` DateTime64(3)
)
ENGINE = KeeperMap('/loom/grant_claims')
PRIMARY KEY claim_key;

-- loom.graph_projections
CREATE TABLE IF NOT EXISTS loom.graph_projections
(
    `token` String,
    `org` String,
    `namespace` String,
    `started_at` DateTime64(3) DEFAULT now64(3),
    `finished` UInt8 DEFAULT 0
)
ENGINE = KeeperMap('/loom/graph_projections')
PRIMARY KEY token;

-- loom.idempotency
CREATE TABLE IF NOT EXISTS loom.idempotency
(
    `idempotency_key` String,
    `org` String DEFAULT '',
    `subject` String DEFAULT '',
    `body_hash` String,
    `operation` LowCardinality(String),
    `status_code` UInt16,
    `response_body` String,
    `response_headers` String DEFAULT '{}',
    `created_at` DateTime DEFAULT now(),
    `expires_at` DateTime
)
ENGINE = ReplacingMergeTree(created_at)
ORDER BY idempotency_key
TTL expires_at
SETTINGS index_granularity = 64, non_replicated_deduplication_window = 1000;

-- loom.instances
CREATE TABLE IF NOT EXISTS loom.instances
(
    `instance_id` String,
    `deployment` UInt8 DEFAULT 0,
    `label` String DEFAULT '',
    `host` String DEFAULT '',
    `pid` UInt32 DEFAULT 0,
    `build_commit` String DEFAULT '',
    `schema_version` UInt32 DEFAULT 0,
    `serving` UInt8 DEFAULT 1,
    `workers_lease` String DEFAULT '',
    `settings_fp` String DEFAULT '',
    `keys_fp` String DEFAULT '',
    `config_fp` String DEFAULT '',
    `started_at` DateTime64(3) DEFAULT now64(3),
    `heartbeat_at` DateTime64(3) DEFAULT now64(3),
    `stopped` UInt8 DEFAULT 0
)
ENGINE = KeeperMap('/loom/instances')
PRIMARY KEY instance_id;

-- loom.keyring_readers
CREATE TABLE IF NOT EXISTS loom.keyring_readers
(
    `process` String,
    `refresh_seconds` Float64,
    `seen_at` DateTime64(3) DEFAULT now64(3)
)
