-- loom.memory_embeddings
CREATE TABLE IF NOT EXISTS loom.memory_embeddings
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String,
    `session_id` String,
    `memory_key` String,
    `memory_type` LowCardinality(String),
    `scope` Enum8('private' = 1, 'shared' = 2),
    `content_excerpt` String CODEC(ZSTD(3)),
    `embedding_model` LowCardinality(String),
    `embedding_dim` UInt16 DEFAULT 0,
    `embedding` Array(BFloat16) CODEC(Quantized('rabitq', 3072, 0)),
    `tombstoned_at` Nullable(DateTime),
    `created_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `embed_attempts` UInt16 DEFAULT 0,
    `embed_last_error` String DEFAULT '',
    `embed_failed_at` Nullable(DateTime),
    `run_id` String DEFAULT '-',
    `entities` Array(LowCardinality(String)) DEFAULT [],
    `conflict_checked_at` Nullable(DateTime),
    `tags` Array(String) DEFAULT [],
    `files` Array(String) DEFAULT [],
    `concepts` Array(String) DEFAULT [],
    `status` Enum8('active' = 1, 'conflicted' = 2, 'tombstoned' = 3, 'duplicate' = 4, 'superseded' = 5, 'rejected' = 6, 'proposed' = 7) DEFAULT 'active',
    `confidence` Float32 DEFAULT 1.,
    `temporal_anchor` Nullable(DateTime) DEFAULT NULL,
    `temporal_confidence` Float32 DEFAULT 0,
    `valid_at` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `invalid_at` Nullable(DateTime) DEFAULT NULL,
    `content_excerpt_lc` String MATERIALIZED lower(content_excerpt) CODEC(ZSTD(3)),
    `memory_key_embedding` Array(BFloat16) DEFAULT [] CODEC(Quantized('rabitq', 3072, 0)),
    `memory_key_embedding_dim` UInt16 DEFAULT 0,
    `reinforcement_count` UInt32 DEFAULT 1,
    `last_reinforced_at` DateTime DEFAULT now(),
    `mentioned_at` Nullable(DateTime) DEFAULT NULL,
    `source_resource_id` String DEFAULT '',
    `source_class` LowCardinality(String) DEFAULT '',
    `verified` UInt8 DEFAULT 0,
    `content_excerpt_stem` String MATERIALIZED arrayStringConcat(arrayMap(t -> stem(t, 'en'), splitByNonAlpha(lower(content_excerpt))), ' ') CODEC(ZSTD(3)),
    `content_excerpt_lemma` String DEFAULT '' CODEC(ZSTD(3)),
    `expires_at` Nullable(DateTime) DEFAULT NULL,
    `content_sha256` String DEFAULT '',
    `embed_retry_at` Nullable(DateTime64(3, 'UTC')) DEFAULT NULL,
    INDEX entities_skip entities TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX conflict_checked_at_skip conflict_checked_at TYPE minmax GRANULARITY 4,
    INDEX tags_skip tags TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX memory_key_ngram memory_key TYPE ngrambf_v1(3, 4096, 2, 0) GRANULARITY 4,
    INDEX status_skip status TYPE set(8) GRANULARITY 4,
    INDEX idx_memory_embeddings_source source_resource_id TYPE bloom_filter GRANULARITY 4,
    INDEX files_skip files TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX concepts_skip concepts TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX idx_valid_to_minmax valid_to TYPE minmax GRANULARITY 8,
    INDEX idx_invalid_at_minmax invalid_at TYPE minmax GRANULARITY 8,
    INDEX version_minmax version TYPE minmax GRANULARITY 1
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, agent, user_id, session_id, scope, embedding_model, memory_key)
SETTINGS index_granularity = 256, min_bytes_for_wide_part = 134217728, exclude_materialize_skip_indexes_on_merge = 'embedding_hnsw_idx', enable_block_number_column = 1, enable_block_offset_column = 1, non_replicated_deduplication_window = 1000;

-- loom.memory_evidence
CREATE TABLE IF NOT EXISTS loom.memory_evidence
(
    `evidence_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `run_id` String DEFAULT '-',
    `source_type` LowCardinality(String) DEFAULT 'message',
    `role` LowCardinality(String) DEFAULT '',
    `actor` String DEFAULT '',
    `content` String CODEC(ZSTD(3)),
    `content_lc` String MATERIALIZED lowerUTF8(content) CODEC(ZSTD(3)),
    `content_sha256` FixedString(64),
    `source_resource_id` String DEFAULT '',
    `observed_at` DateTime DEFAULT now(),
    `created_at` DateTime DEFAULT now(),
    `metadata` String DEFAULT '{}',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = ReplacingMergeTree(created_at)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, agent, user_id, session_id, observed_at, evidence_id)
SETTINGS index_granularity = 256, non_replicated_deduplication_window = 1000;

-- loom.memory_exposure_breadth_hourly
CREATE TABLE IF NOT EXISTS loom.memory_exposure_breadth_hourly
(
    `hour` DateTime,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `actor` String,
    `agent` LowCardinality(String),
    `keys_state` AggregateFunction(uniqExact, String),
    `calls_state` AggregateFunction(uniqExact, String),
    `ts_hwm` SimpleAggregateFunction(max, DateTime64(3)) DEFAULT toDateTime64(0, 3)
)
ENGINE = AggregatingMergeTree
PARTITION BY toYYYYMM(hour)
ORDER BY (org, namespace, actor, agent, hour)
TTL hour + toIntervalDay(180)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_exposures
CREATE TABLE IF NOT EXISTS loom.memory_exposures
(
    `ts` DateTime DEFAULT now(),
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `actor` String DEFAULT '',
    `token_id` String DEFAULT '',
    `agent` LowCardinality(String) DEFAULT '',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `run_id` String DEFAULT '-',
    `operation` LowCardinality(String),
    `request_id` String DEFAULT '',
    `read_scope` LowCardinality(String) DEFAULT 'namespace',
    `query_digest` String DEFAULT '',
    `top_k` UInt16 DEFAULT 0,
    `returned_keys` Array(String),
    `returned_count` UInt16 DEFAULT 0,
    `below_floor_count` UInt16 DEFAULT 0
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, actor, ts)
TTL ts + toIntervalDay(180)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_extraction_queue
CREATE TABLE IF NOT EXISTS loom.memory_extraction_queue
(
    `org` String,
    `namespace` String,
    `agent` String,
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `queue_id` String,
    `payload` String CODEC(ZSTD(3)),
    `message_count` UInt32,
    `content_chars` UInt32,
    `status` LowCardinality(String) DEFAULT 'pending',
    `attempts` UInt8 DEFAULT 0,
    `lease_until` DateTime64(3) DEFAULT toDateTime64(0, 3),
    `last_error` String DEFAULT '',
    `written` UInt32 DEFAULT 0,
    `enqueued_at` DateTime64(3) DEFAULT now64(3),
    `updated_at` DateTime64(3) DEFAULT now64(3),
    `version` UInt64,
    `enqueued_by` String DEFAULT ''
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY toYYYYMM(enqueued_at)
ORDER BY (org, namespace, agent, user_id, session_id, queue_id)
TTL enqueued_at + toIntervalDay(30)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_projection_failures
CREATE TABLE IF NOT EXISTS loom.memory_projection_failures
(
    `failure_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String) DEFAULT '',
    `projection` LowCardinality(String),
    `source_operation` LowCardinality(String) DEFAULT '',
    `source_resource_id` String DEFAULT '',
    `memory_keys` Array(String) DEFAULT [],
    `error_type` LowCardinality(String) DEFAULT '',
    `error_message` String DEFAULT '',
    `payload` String DEFAULT '{}',
    `status` Enum8('active' = 1, 'resolved' = 2, 'abandoned' = 3) DEFAULT 'active',
    `created_at` DateTime DEFAULT now(),
    `resolved_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = MergeTree
ORDER BY (org, namespace, projection, created_at, failure_id)
TTL coalesce(resolved_at, created_at) + toIntervalDay(30) WHERE status = 'resolved'
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_record_conflicts
CREATE TABLE IF NOT EXISTS loom.memory_record_conflicts
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `schema_name` LowCardinality(String),
    `memory_key` String,
    `field_name` String,
    `prior_value` String DEFAULT '',
    `incoming_value` String DEFAULT '',
    `prior_record_id` UUID,
    `incoming_record_id` UUID,
    `prior_memory_id` Nullable(UUID),
    `incoming_memory_id` Nullable(UUID),
    `detected_at` DateTime DEFAULT now(),
    `resolved_at` Nullable(DateTime) DEFAULT NULL,
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, schema_name, memory_key, field_name, incoming_record_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_record_fields
CREATE TABLE IF NOT EXISTS loom.memory_record_fields
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `schema_name` LowCardinality(String),
    `record_id` UUID,
    `field_name` LowCardinality(String),
    `field_type` LowCardinality(String),
    `value_string` String DEFAULT '',
    `value_number` Float64 DEFAULT 0,
    `value_bool` Bool DEFAULT false,
    `value_state` Enum8('value' = 1, 'unknown' = 2, 'rejected' = 3, 'absent' = 4) DEFAULT 'value',
    `evidence_id` Nullable(UUID),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `created_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    INDEX record_field_value_bloom value_string TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, schema_name, field_name, record_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_record_versions
CREATE TABLE IF NOT EXISTS loom.memory_record_versions
(
    `record_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `schema_id` UUID,
    `schema_name` LowCardinality(String),
    `memory_key` String DEFAULT '',
    `memory_id` Nullable(UUID),
    `identity_agent` LowCardinality(String) DEFAULT '',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `record_json` String DEFAULT '{}',
    `status` Enum8('active' = 1, 'superseded' = 2, 'rejected' = 3, 'tombstoned' = 4) DEFAULT 'active',
    `valid_at` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    INDEX record_id_skip record_id TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, schema_name, memory_key, record_id, version)
SETTINGS index_granularity = 128, non_replicated_deduplication_window = 1000;

-- loom.memory_records
CREATE TABLE IF NOT EXISTS loom.memory_records
(
    `record_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `schema_id` UUID,
    `schema_name` LowCardinality(String),
    `memory_key` String DEFAULT '',
    `memory_id` Nullable(UUID),
    `identity_agent` LowCardinality(String) DEFAULT '',
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `record_json` String DEFAULT '{}',
    `status` Enum8('active' = 1, 'superseded' = 2, 'rejected' = 3, 'tombstoned' = 4) DEFAULT 'active',
    `valid_at` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL,
    INDEX record_memory_bloom memory_key TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, schema_name, memory_key, record_id)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_reinforcement
CREATE TABLE IF NOT EXISTS loom.memory_reinforcement
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String DEFAULT '-',
    `memory_key` String,
    `reinforcement_count` UInt32 DEFAULT 1,
    `last_reinforced_at` DateTime DEFAULT now(),
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9)))
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, agent, user_id, memory_key)
SETTINGS index_granularity = 64, non_replicated_deduplication_window = 1000;

-- loom.memory_schema_fields
CREATE TABLE IF NOT EXISTS loom.memory_schema_fields
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `schema_id` UUID,
    `field_name` LowCardinality(String),
    `field_type` LowCardinality(String),
    `required` Bool DEFAULT false,
    `identity` Bool DEFAULT false,
    `enum_values` Array(String) DEFAULT [],
    `constraints` String DEFAULT '{}',
    `description` String DEFAULT '',
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `created_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, schema_id, field_name)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_schemas
CREATE TABLE IF NOT EXISTS loom.memory_schemas
(
    `schema_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `name` LowCardinality(String),
    `description` String DEFAULT '',
    `status` Enum8('active' = 1, 'proposed' = 2, 'rejected' = 3, 'tombstoned' = 4) DEFAULT 'active',
    `version` UInt64 DEFAULT toUInt64(toUnixTimestamp64Nano(now64(9))),
    `created_at` DateTime DEFAULT now(),
    `created_by` String DEFAULT '',
    `tombstoned_at` Nullable(DateTime) DEFAULT NULL
)
ENGINE = ReplacingMergeTree(version)
ORDER BY (org, namespace, name)
