        String,
        String,
        String,
        String,
        String,
        String)),
    `df_added_at` DateTime DEFAULT now(),
    `ts_hwm` SimpleAggregateFunction(max, UInt64) DEFAULT 0
)
ENGINE = AggregatingMergeTree
PARTITION BY toYYYYMM(df_added_at)
ORDER BY (org, namespace, term)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 256, non_replicated_deduplication_window = 1000;

-- loom.memory_usage_events
CREATE TABLE IF NOT EXISTS loom.memory_usage_events
(
    `memory_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `event_type` LowCardinality(String),
    `event_count` Int32,
    `ts` DateTime DEFAULT now(),
    `agent` LowCardinality(String) DEFAULT '',
    `consumer` LowCardinality(String) DEFAULT ''
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, memory_id, ts)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_usage_totals
CREATE TABLE IF NOT EXISTS loom.memory_usage_totals
(
    `memory_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `evidence_count` Int64,
    `recall_count` Int64,
    `used_count` Int64,
    `harm_count` Int64,
    `last_recalled_at` SimpleAggregateFunction(max, DateTime),
    `bumped_at` SimpleAggregateFunction(max, DateTime)
)
ENGINE = SummingMergeTree
ORDER BY (org, namespace, memory_id)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.memory_versions
CREATE TABLE IF NOT EXISTS loom.memory_versions
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String,
    `session_id` String,
    `memory_key` String,
    `memory_type` LowCardinality(String),
    `value` String,
    `value_json` JSON DEFAULT '{}',
    `confidence` Float32 DEFAULT 1.,
    `source_trace` String DEFAULT '',
    `version` UInt64,
    `tombstoned_at` Nullable(DateTime),
    `created_at` DateTime DEFAULT now(),
    `expires_at` Nullable(DateTime),
    `pinned` UInt8 DEFAULT 0,
    `run_id` String DEFAULT '-',
    `entities` Array(LowCardinality(String)) DEFAULT [],
    `memory_id` UUID DEFAULT generateUUIDv4(),
    `redacted_at` Nullable(DateTime),
    `redaction_reason` String DEFAULT '',
    `status` Enum8('active' = 1, 'conflicted' = 2, 'tombstoned' = 3, 'duplicate' = 4, 'superseded' = 5, 'rejected' = 6, 'proposed' = 7) DEFAULT 'active',
    `conflict_with` Array(UUID) DEFAULT [],
    `duplicate_of` String DEFAULT '',
    `evidence_count` UInt32 DEFAULT 1,
    `recall_count` UInt32 DEFAULT 0,
    `last_recalled_at` Nullable(DateTime),
    `cross_promoted_from_memory_id` Nullable(UUID) DEFAULT NULL,
    `cross_promoted_from_namespace` String DEFAULT '',
    `tags` Array(String) DEFAULT [],
    `files` Array(String) DEFAULT [],
    `concepts` Array(String) DEFAULT [],
    `superseded_by` String DEFAULT '',
    `rejection_reason` String DEFAULT '',
    `temporal_anchor` Nullable(DateTime) DEFAULT NULL,
    `temporal_confidence` Float32 DEFAULT 0,
    `updated_at` DateTime DEFAULT now(),
    `valid_at` Nullable(DateTime) DEFAULT NULL,
    `valid_to` Nullable(DateTime) DEFAULT NULL,
    `invalid_at` Nullable(DateTime) DEFAULT NULL,
    `char_limit` Nullable(UInt32),
    `reinforcement_count` UInt32 DEFAULT 1,
    `last_reinforced_at` DateTime DEFAULT now(),
    `mentioned_at` Nullable(DateTime) DEFAULT NULL,
    `source_resource_id` String DEFAULT '',
    `content_sha256` FixedString(64) DEFAULT '0',
    `verified_by` String DEFAULT '',
    `verified_at` Nullable(DateTime) DEFAULT NULL,
    `verified_sha256` String DEFAULT '',
    `grounding` LowCardinality(String) DEFAULT '',
    `evidence` String DEFAULT '',
    `lock_mode` LowCardinality(String) DEFAULT '',
    `lock_reason` String DEFAULT '',
    `lock_until` Nullable(DateTime) DEFAULT NULL,
    `locked_by` String DEFAULT '',
    `locked_at` Nullable(DateTime) DEFAULT NULL,
    `on_expire` LowCardinality(String) DEFAULT '',
    `expire_reason` String DEFAULT '',
    `actor` String DEFAULT '',
    `source_class` LowCardinality(String) DEFAULT '',
    `sensitivity` LowCardinality(String) DEFAULT '',
    `value_preview` String MATERIALIZED substring(value, 1, 2048),
    `value_len` UInt32 MATERIALIZED length(value),
    INDEX memory_id_skip memory_id TYPE bloom_filter(0.01) GRANULARITY 4
)
ENGINE = ReplacingMergeTree
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, agent, user_id, session_id, memory_key, version)
SETTINGS index_granularity = 128, non_replicated_deduplication_window = 1000;

-- loom.memory_webhook_attempts
CREATE TABLE IF NOT EXISTS loom.memory_webhook_attempts
(
    `event_id` String,
    `status` LowCardinality(String),
    `attempts` UInt16,
    `next_attempt_at` DateTime64(3),
    `last_status` UInt16 DEFAULT 0,
    `last_error` String DEFAULT '',
    `recorded_at` DateTime64(3) DEFAULT now64(3),
    `version` UInt64
)
ENGINE = MergeTree
PARTITION BY toDate(recorded_at)
ORDER BY (event_id, version)
TTL toDateTime(recorded_at) + toIntervalDay(3)
SETTINGS non_replicated_deduplication_window = 1000, ttl_only_drop_parts = 1, index_granularity = 8192;

-- loom.memory_webhook_outbox
CREATE TABLE IF NOT EXISTS loom.memory_webhook_outbox
(
    `org` LowCardinality(String),
