ORDER BY (org, namespace, plane)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.namespaces
CREATE TABLE IF NOT EXISTS loom.namespaces
(
    `org` LowCardinality(String),
    `namespace` String,
    `owner_email` String,
    `description` String DEFAULT '',
    `tags` Array(LowCardinality(String)) DEFAULT [],
    `active` Bool DEFAULT true,
    `auto_promote_enabled` Bool DEFAULT false,
    `created_at` DateTime DEFAULT now(),
    `updated_at` DateTime DEFAULT now(),
    `learnings_review_enabled` Bool DEFAULT false,
    `conflict_threshold` Nullable(Float32),
    `retention_days` UInt16 DEFAULT 0,
    `warm_days` UInt16 DEFAULT 0,
    `conversation_seeder_enabled` Bool DEFAULT false,
    `duplicate_threshold` Nullable(Float32),
    `visibility` Enum8('private' = 0, 'public' = 1) DEFAULT 'private',
    `kind` LowCardinality(String) DEFAULT 'memory',
    `rerank_endpoint` String DEFAULT '',
    `rerank_prompt_template` String DEFAULT '',
    `default_conflict_policy` LowCardinality(String) DEFAULT 'auto_reinforce',
    `auto_promote_gate` LowCardinality(String) DEFAULT 'k_supporters',
    `evidence_threshold` UInt32 DEFAULT 5,
    `classify_endpoint` String DEFAULT '',
    `classify_prompt_template` String DEFAULT '',
    `password_hash` String DEFAULT '',
    `requires_approval` Bool DEFAULT false,
    `daily_cost_cap_usd` Float32 DEFAULT 0.,
    `consolidation_enabled` Bool DEFAULT false,
    `contact_email` String DEFAULT '',
    `conversation_logging_enabled` Bool DEFAULT false,
    `capture_generation_io` Nullable(Bool) DEFAULT NULL,
    `coverage_sweep` Nullable(Bool) DEFAULT NULL,
    `classification` Enum8('standard' = 0, 'restricted' = 1) DEFAULT 'standard',
    `join_policy` Enum8('inherit' = 0, 'open' = 1, 'approval' = 2, 'closed' = 3) DEFAULT 'inherit',
    `retrieval_defaults` String DEFAULT '',
    `proposal_policy` String DEFAULT '',
    `code_change_policy` LowCardinality(String) DEFAULT '',
    `released_aliases` Array(String) DEFAULT []
)
ENGINE = ReplacingMergeTree(updated_at)
PARTITION BY org
ORDER BY (org, namespace)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.oauth_claims
CREATE TABLE IF NOT EXISTS loom.oauth_claims
(
    `claim_key` String,
    `holder` String,
    `claimed_at` DateTime64(3)
)
ENGINE = KeeperMap('/loom/oauth_claims')
PRIMARY KEY claim_key;

-- loom.oauth_signin_state
CREATE TABLE IF NOT EXISTS loom.oauth_signin_state
(
    `claim_key` String,
    `value` String,
    `expires_at` UInt32
)
ENGINE = KeeperMap('/loom/oauth_signin_state', 500000)
PRIMARY KEY claim_key;

-- loom.oauth_state
CREATE TABLE IF NOT EXISTS loom.oauth_state
(
    `record_type` LowCardinality(String),
    `id` String,
    `client_id` String DEFAULT '',
    `redirect_uri` String DEFAULT '',
    `redirect_uris` Array(String) DEFAULT [],
    `client_name` String DEFAULT '',
    `code_challenge` String DEFAULT '',
    `subject` String DEFAULT '',
    `org` String DEFAULT '',
    `namespaces` Array(String) DEFAULT [],
    `roles` Array(String) DEFAULT [],
    `consumed` UInt8 DEFAULT 0,
    `created_at` DateTime DEFAULT now(),
    `expires_at` UInt32 DEFAULT 0,
    `version` UInt64 DEFAULT toUnixTimestamp64Nano(now64(9)),
    `family` String DEFAULT '',
    `upstream_refresh` String DEFAULT '',
    `generation` UInt32 DEFAULT 0
)
ENGINE = ReplacingMergeTree(version)
PARTITION BY record_type
ORDER BY (record_type, id)
TTL created_at + toIntervalDay(90)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.operator_edges
CREATE TABLE IF NOT EXISTS loom.operator_edges
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `from_key` String,
    `to_key` String,
    `relation` LowCardinality(String) DEFAULT '',
    `label` String DEFAULT '',
    `explanation` String DEFAULT '',
    `evidence` Array(String) DEFAULT [],
    `confidence` Float32 DEFAULT 1.,
    `weight` Float32 DEFAULT 1.,
    `author` LowCardinality(String) DEFAULT '',
    `run_id` String DEFAULT '-',
    `created_at` DateTime DEFAULT now(),
    `tombstoned_at` Nullable(DateTime),
    INDEX idx_operator_edges_to to_key TYPE bloom_filter GRANULARITY 4
)
ENGINE = ReplacingMergeTree(created_at)
PARTITION BY toYYYYMM(created_at)
ORDER BY (org, namespace, from_key, to_key, relation)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.org_model_calls
CREATE TABLE IF NOT EXISTS loom.org_model_calls
(
    `org` String,
    `enabled` UInt8,
    `reason` String,
    `updated_by` String,
    `updated_at` DateTime64(3, 'UTC'),
    `locked` UInt8,
    `locked_by` String,
    `version` UInt64
)
ENGINE = ReplacingMergeTree(version)
ORDER BY org
SETTINGS non_replicated_deduplication_window = 1000, index_granularity = 8192;

-- loom.policy_decisions
CREATE TABLE IF NOT EXISTS loom.policy_decisions
(
    `ts` DateTime64(3) DEFAULT now64(),
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `user_id` String DEFAULT '-',
    `session_id` String DEFAULT '-',
    `operation` LowCardinality(String),
    `request_id` String DEFAULT '',
    `mode` LowCardinality(String),
    `decision` LowCardinality(String),
    `enforced` Bool DEFAULT false,
    `determining_rules` Array(String) DEFAULT [],
    `errors` Array(String) DEFAULT [],
    `detail` String DEFAULT '',
    `latency_ms` UInt32 DEFAULT 0
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(ts)
ORDER BY (org, namespace, ts)
TTL toDateTime(ts) + toIntervalDay(90)
SETTINGS index_granularity = 8192, non_replicated_deduplication_window = 1000;

-- loom.principal_groups
CREATE TABLE IF NOT EXISTS loom.principal_groups
(
    `org` LowCardinality(String),
