-- loom.query_nodes
CREATE TABLE IF NOT EXISTS loom.query_nodes
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `query_hash` UInt64,
    `query` SimpleAggregateFunction(anyLast, String),
    `embedding_model` SimpleAggregateFunction(anyLast, String),
    `embedding_dim` SimpleAggregateFunction(anyLast, UInt16),
    `embedding` SimpleAggregateFunction(anyLast, Array(BFloat16)),
    `returned_keys` SimpleAggregateFunction(anyLast, Array(String)),
    `sessions` SimpleAggregateFunction(groupUniqArrayArray, Array(String)),
    `hits` SimpleAggregateFunction(sum, UInt64),
    `abstains` SimpleAggregateFunction(sum, UInt64),
    `first_seen` SimpleAggregateFunction(min, DateTime),
    `last_seen` SimpleAggregateFunction(max, DateTime)
)
ENGINE = AggregatingMergeTree
ORDER BY (org, namespace, query_hash)
SETTINGS allow_dimensions_outside_sorting_key = 1, index_granularity = 8192, non_replicated_deduplication_window = 1000;

