-- loom.agent_cost_rollup_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.agent_cost_rollup_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom.agent_cost_rollup_daily
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `agent` LowCardinality(String),
    `day` Date,
    `operation` LowCardinality(String),
    `cost_usd_state` AggregateFunction(sum, Decimal(18, 6)),
    `tokens_state` AggregateFunction(sum, UInt64),
    `embed_tokens_state` AggregateFunction(sum, UInt64),
    `ops_state` AggregateFunction(count),
    `errors_state` AggregateFunction(sum, UInt64),
    `latency_sum_state` AggregateFunction(sum, UInt64),
    `latency_quantile_state` AggregateFunction(quantiles(0.5, 0.95, 0.99), UInt32),
    `ts_hwm` DateTime64(3)
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    org,
    namespace,
    agent,
    toDate(ts) AS day,
    operation,
    sumState(upstream_cost_usd) AS cost_usd_state,
    sumState(toUInt64(input_tokens) + toUInt64(output_tokens)) AS tokens_state,
    sumState(toUInt64(embedding_tokens)) AS embed_tokens_state,
    countState() AS ops_state,
    sumStateIf(toUInt64(1), success = false) AS errors_state,
    sumState(toUInt64(latency_ms)) AS latency_sum_state,
    quantilesState(0.5, 0.95, 0.99)(latency_ms) AS latency_quantile_state,
    max(ts) AS ts_hwm
FROM loom.agent_events
WHERE (ts > (
    SELECT max(ts_hwm)
    FROM loom.agent_cost_rollup_daily
)) AND (ts <= (now64(3) - toIntervalSecond(10)))
GROUP BY
    org,
    namespace,
    agent,
    day,
    operation;

-- loom.chunk_context_term_freq_mv
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.chunk_context_term_freq_mv TO loom.chunk_term_freq
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `term` String,
    `df_state` AggregateFunction(uniqExact, Tuple(
        String,
        UInt32)),
    `df_added_at` DateTime
)
AS SELECT
    org,
    namespace,
    term,
    uniqExactState((source_uri, chunk_idx)) AS df_state,
    now() AS df_added_at
FROM loom.chunks
ARRAY JOIN arrayDistinct(arrayFilter(t -> (length(t) >= 3), arrayMap(t -> lowerUTF8(t), splitByNonAlpha(context)))) AS term
WHERE (content != '') AND (context != '') AND (doc_superseded_at IS NULL)
GROUP BY
    org,
    namespace,
    term;

-- loom.chunk_term_freq_mv
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.chunk_term_freq_mv TO loom.chunk_term_freq
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `term` String,
    `df_state` AggregateFunction(uniqExact, Tuple(
        String,
        UInt32)),
    `df_added_at` DateTime
)
AS SELECT
    org,
    namespace,
    term,
    uniqExactState((source_uri, chunk_idx)) AS df_state,
    now() AS df_added_at
FROM loom.chunks
ARRAY JOIN arrayDistinct(arrayFilter(t -> (length(t) >= 3), arrayMap(t -> lowerUTF8(t), splitByNonAlpha(content)))) AS term
WHERE (content != '') AND (doc_superseded_at IS NULL)
GROUP BY
    org,
    namespace,
    term;

-- loom.code_doc_stats_mv
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.code_doc_stats_mv TO loom.code_doc_stats
(
