-- loom.code_term_df_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.code_term_df_refresh
REFRESH EVERY 1 HOUR TO loom.code_term_df
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `term` String,
    `df` UInt32,
    `avgdl` Float32,
    `refreshed_at` DateTime
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    org,
    namespace,
    term,
    toUInt32(uniqExactMerge(df_state)) AS df,
    toFloat32(0) AS avgdl,
    now() AS refreshed_at
FROM loom.code_term_freq
WHERE term != ''
GROUP BY
    org,
    namespace,
    term
UNION ALL
SELECT
    org,
    namespace,
    '' AS term,
    toUInt32(count()) AS df,
    toFloat32(avgOrDefault(token_count)) AS avgdl,
    now() AS refreshed_at
FROM loom.code_doc_stats
FINAL
GROUP BY
    org,
    namespace
SETTINGS optimize_aggregation_in_order = 1;

-- loom.code_term_freq_mv
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.code_term_freq_mv TO loom.code_term_freq
(
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `term` String,
    `df_state` AggregateFunction(uniqExact, UUID),
    `df_added_at` DateTime
)
AS SELECT
    org,
    namespace,
    term,
    uniqExactState(chunk_id) AS df_state,
    now() AS df_added_at
FROM loom.code_chunks
ARRAY JOIN arrayDistinct(arrayFilter(t -> (length(t) >= 2), splitByChar(' ', lexemes))) AS term
WHERE (lexemes != '') AND (tombstoned_at IS NULL)
GROUP BY
    org,
    namespace,
    term;

