-- loom.memory_doc_stats_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.memory_doc_stats_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom.memory_doc_stats
(
    `org` String,
    `namespace` String,
    `agent` String,
    `user_id` String,
    `session_id` String,
    `scope` Enum8('private' = 1, 'shared' = 2),
    `embedding_model` String,
    `memory_key` String,
    `excerpt_length` UInt32,
    `version` UInt64,
    `stats_at` DateTime,
    `ts_hwm` UInt64
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    org,
    namespace,
    agent,
    user_id,
    session_id,
    scope,
    embedding_model,
    memory_key,
    toUInt32(length(content_excerpt)) AS excerpt_length,
    version,
    now() AS stats_at,
    version AS ts_hwm
FROM loom.memory_embeddings
WHERE (embedding_dim > 0) AND (tombstoned_at IS NULL) AND (version > (
    SELECT max(ts_hwm)
    FROM loom.memory_doc_stats
    WHERE (org = '') AND (namespace = '')
)) AND (version <= toUInt64(toUnixTimestamp64Nano(now64(9) - toIntervalSecond(10))))
UNION ALL
SELECT
    '' AS org,
    '' AS namespace,
    '' AS agent,
    '' AS user_id,
    '' AS session_id,
    CAST('private', 'Enum8(\'private\' = 1, \'shared\' = 2)') AS scope,
    '' AS embedding_model,
    '' AS memory_key,
    toUInt32(0) AS excerpt_length,
    max(version) AS sentinel_version,
    now() AS stats_at,
    max(version) AS sentinel_hwm
FROM loom.memory_embeddings
WHERE (version > (
    SELECT max(ts_hwm)
    FROM loom.memory_doc_stats
    WHERE (org = '') AND (namespace = '')
)) AND (version <= toUInt64(toUnixTimestamp64Nano(now64(9) - toIntervalSecond(10))))
HAVING max(version) > 0;

-- loom.memory_exposure_breadth_hourly_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.memory_exposure_breadth_hourly_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom.memory_exposure_breadth_hourly
(
    `hour` DateTime,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `actor` String,
    `agent` LowCardinality(String),
    `keys_state` AggregateFunction(uniqExact, String),
    `calls_state` AggregateFunction(uniqExact, String),
    `ts_hwm` DateTime
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    toStartOfHour(ts) AS hour,
    org,
    namespace,
    actor,
    agent,
    uniqExactState(k) AS keys_state,
    uniqExactState(request_id) AS calls_state,
    max(ts) AS ts_hwm
FROM loom.memory_exposures
ARRAY JOIN returned_keys AS k
WHERE (ts > (
    SELECT max(ts_hwm)
    FROM loom.memory_exposure_breadth_hourly
)) AND (ts <= (now64(3) - toIntervalSecond(10)))
GROUP BY
    hour,
    org,
    namespace,
    actor,
    agent;

