    valid_at,
    valid_to,
    version,
    created_at,
    updated_at,
    tombstoned_at
FROM loom.memory_records;

-- loom.memory_term_freq_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.memory_term_freq_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom.memory_term_freq
(
    `org` String,
    `namespace` String,
    `term` String,
    `df_state` AggregateFunction(uniqExact, Tuple(
        String,
        String,
        String,
        String,
        String,
        String)),
    `df_added_at` DateTime,
    `ts_hwm` UInt64
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    org,
    namespace,
    term,
    uniqExactState((toString(agent), user_id, session_id, toString(scope), toString(embedding_model), memory_key)) AS df_state,
    now() AS df_added_at,
    max(version) AS ts_hwm
FROM loom.memory_embeddings
ARRAY JOIN arrayDistinct(arrayFilter(t -> (length(t) >= 3), arrayMap(t -> lowerUTF8(t), splitByNonAlpha(content_excerpt)))) AS term
WHERE (embedding_dim > 0) AND (tombstoned_at IS NULL) AND (version > (
    SELECT max(ts_hwm)
    FROM loom.memory_term_freq
    WHERE (org = '') AND (namespace = '') AND (term = '')
)) AND (version <= toUInt64(toUnixTimestamp64Nano(now64(9) - toIntervalSecond(10))))
GROUP BY
    org,
    namespace,
    term
UNION ALL
SELECT
    '' AS org,
    '' AS namespace,
    '' AS term,
    uniqExactStateIf((toString(agent), user_id, session_id, toString(scope), toString(embedding_model), memory_key), 0) AS df_state,
    now() AS df_added_at,
    max(version) AS sentinel_hwm
FROM loom.memory_embeddings
WHERE (version > (
    SELECT max(ts_hwm)
    FROM loom.memory_term_freq
    WHERE (org = '') AND (namespace = '') AND (term = '')
)) AND (version <= toUInt64(toUnixTimestamp64Nano(now64(9) - toIntervalSecond(10))))
HAVING max(version) > 0;

-- loom.memory_usage_totals_mv
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.memory_usage_totals_mv TO loom.memory_usage_totals
(
    `memory_id` UUID,
    `org` LowCardinality(String),
    `namespace` LowCardinality(String),
    `evidence_count` Int32,
    `recall_count` Int32,
    `used_count` Int32,
    `harm_count` Int32,
    `last_recalled_at` DateTime,
    `bumped_at` DateTime
)
AS SELECT
    memory_id,
    org,
    namespace,
    multiIf(event_type = 'evidence', event_count, 0) AS evidence_count,
    multiIf(event_type = 'recall', event_count, 0) AS recall_count,
    multiIf(event_type = 'used', event_count, 0) AS used_count,
    multiIf(event_type = 'harm', event_count, 0) AS harm_count,
    if(event_type = 'recall', ts, toDateTime(0)) AS last_recalled_at,
    ts AS bumped_at
FROM loom.memory_usage_events;

