-- loom.subject_last_seen_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom.subject_last_seen_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom.subject_last_seen
(
    `org` String,
    `subject` String,
    `last_seen` AggregateFunction(max, DateTime64(3)),
    `ts_hwm` DateTime64(3)
)
DEFINER = loom SQL SECURITY DEFINER
AS SELECT
    org,
    subject,
    maxState(ts) AS last_seen,
    max(ts) AS ts_hwm
FROM loom.agent_events
WHERE (subject != '') AND (ts > (
    SELECT max(ts_hwm)
    FROM loom.subject_last_seen
    WHERE (org = '') AND (subject = '')
)) AND (ts <= (now64(3) - toIntervalSecond(10)))
GROUP BY
    org,
    subject
UNION ALL
SELECT
    '' AS org,
    '' AS subject,
    maxState(toDateTime64(0, 3)) AS last_seen,
    max(ts) AS ts_hwm
FROM loom.agent_events
WHERE (ts > (
    SELECT max(ts_hwm)
    FROM loom.subject_last_seen
    WHERE (org = '') AND (subject = '')
)) AND (ts <= (now64(3) - toIntervalSecond(10)))
HAVING count() > 0;

-- loom_telemetry.sli_minute_refresh
CREATE MATERIALIZED VIEW IF NOT EXISTS loom_telemetry.sli_minute_refresh
REFRESH EVERY 1 MINUTE APPEND TO loom_telemetry.sli_minute
(
    `minute` DateTime,
    `slo_class` String,
    `operation` String,
    `transport` String,
    `traffic_class` String,
    `org` String,
    `requests` UInt64,
    `server_errors` UInt64,
    `client_errors` UInt64,
    `rate_limited` UInt64,
    `slow` UInt64,
    `latency` AggregateFunction(quantilesTDigest(0.5, 0.95, 0.99), UInt32),
    `ingested_hwm` Nullable(DateTime64(3))
)
DEFINER = loom SQL SECURITY DEFINER
AS WITH
    greatest((
        SELECT max(ingested_hwm)
        FROM loom_telemetry.sli_minute
        WHERE (slo_class = '') AND (minute >= toStartOfMinute(now() - toIntervalDay(31)))
    ), now64(3) - toIntervalDay(31)) AS folded,
    (
        SELECT min(ingested_at)
        FROM loom.agent_events
        WHERE (kind = 'request') AND (slo_class != '') AND (ts >= (now64(3) - toIntervalDay(31))) AND (ingested_at > folded)
    ) AS first_unfolded,
    least(if(first_unfolded > folded, first_unfolded + toIntervalHour(1), now64(3)), now64(3) - toIntervalSecond(70)) AS fold_to
SELECT
    toStartOfMinute(ts) AS minute,
    slo_class,
    operation,
    transport,
    traffic_class,
    org,
    count() AS requests,
    countIf(status_class = 'server') AS server_errors,
    countIf(status_class = 'client') AS client_errors,
    countIf(error_code = 'RATE_LIMITED') AS rate_limited,
    countIf((status_class = 'ok') AND (latency_ms > budget_ms)) AS slow,
    quantilesTDigestStateIf(0.5, 0.95, 0.99)(latency_ms, status_class = 'ok') AS latency,
    fold_to AS ingested_hwm
FROM loom.agent_events
WHERE (kind = 'request') AND (slo_class != '') AND (ts >= (now64(3) - toIntervalDay(31))) AND (ingested_at > folded) AND (ingested_at <= fold_to)
GROUP BY
    minute,
    slo_class,
    operation,
    transport,
    traffic_class,
    org
UNION ALL
WITH
    greatest((
        SELECT max(ingested_hwm)
        FROM loom_telemetry.sli_minute
        WHERE (slo_class = '') AND (minute >= toStartOfMinute(now() - toIntervalDay(31)))
    ), now64(3) - toIntervalDay(31)) AS folded,
    (
        SELECT min(ingested_at)
        FROM loom.agent_events
        WHERE (kind = 'request') AND (slo_class != '') AND (ts >= (now64(3) - toIntervalDay(31))) AND (ingested_at > folded)
    ) AS first_unfolded,
    least(if(first_unfolded > folded, first_unfolded + toIntervalHour(1), now64(3)), now64(3) - toIntervalSecond(70)) AS fold_to
SELECT
    toStartOfDay(now()) AS minute,
    '' AS slo_class,
    '' AS operation,
    '' AS transport,
    '' AS traffic_class,
    '' AS org,
    0 AS requests,
    0 AS server_errors,
    0 AS client_errors,
    0 AS rate_limited,
    0 AS slow,
    quantilesTDigestStateIf(0.5, 0.95, 0.99)(toUInt32(0), false) AS latency,
    fold_to AS ingested_hwm
HAVING fold_to > folded
SETTINGS max_insert_threads = 1, min_insert_block_size_rows = 1000000000000, min_insert_block_size_bytes = 0;
